    getSettingsReminders: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Default Response */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @description The catalog categories a preparation line can name (read-only here; Settings → Catalog edits them) */
                        categories: {
                            active: boolean;
                            colour: string;
                            key: string;
                            label: string;
                        }[];
                        leads: {
                            businessHoursOnly: boolean;
                            /** @description 15 to 1440 minutes after their last text */
                            followUpDelayMin: number;
                            /** @description One automatic follow-up text to a lead who did not book */
                            followUpEnabled: boolean;
                            /** @description Only within this many hours of their last text, 1 to 24 */
                            withinHours: number;
                        };
                        /** @description Read-only: automated texts wait for the end of quiet hours */
                        quietHours: {
                            enabled: boolean;
                            end: string;
                            start: string;
                        };
                        reminders: {
                            /** @description The preparation line added to the reminder of a visit holding that category (e.g. tint: "Plan for 2–3 hours."), 160 characters at most */
                            categoryPrep: {
                                [key: string]: string;
                            };
                            /** @description A booked visit that is not confirmed yet is asked to "Reply C to confirm"; off: it gets the plain reminder */
                            confirmRequest: boolean;
                            /** @description Minutes before the visit, longest first (at most 5, each 1 to 10080); [] turns appointment reminders off */
                            offsetsMin: number[];
                            /** @description One review request 2 hours after a completed visit (reviews.enabled) */
                            reviewRequest: boolean;
                        };
                        statusTexts: {
                            /** @description The picked-up text carries a book-again link (only to clients with marketing-grade consent) */
                            bookAgainLink: boolean;
                            checkedIn: boolean;
                            /** @description 0 to 30; the text is dropped when the wash starts first */
                            checkedInDelayMin: number;
                            /** @description Minutes past the promised end before the first "running late" text, 0 to 120 */
                            lateGraceMin: number;
                            /** @description At most this many per visit, 0 to 2 */
                            lateMax: number;
                            pickedUp: boolean;
                            ready: boolean;
                            runningLate: boolean;
                        };
                        /** @description The section’s version (ETag): send it back with PUT */
                        version: number;
                    };
                };
            };
        };
    };
